"use client"

import { useState, useEffect } from "react"
import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet"
import "leaflet/dist/leaflet.css"
import L from "leaflet"
import {
  Hospital,
  Shield,
  FireExtinguisher,
  Landmark,
  School,
  Building2,
  Navigation,
} from "lucide-react"

// Sample locations
const locations = [
  {
    id: 1,
    name: "Calapan City Hospital",
    category: "Hospital",
    lat: 13.4103,
    lng: 121.1803,
    address: "Gov. Antonio St, Calapan City, Oriental Mindoro",
    phone: "0917-123-4567",
  },
  {
    id: 2,
    name: "Calapan City Police Station",
    category: "Police",
    lat: 13.4142,
    lng: 121.1815,
    address: "City Hall Compound, Calapan City, Oriental Mindoro",
    phone: "0917-765-4321",
  },
  {
    id: 3,
    name: "Calapan City Fire Station",
    category: "Fire Dept",
    lat: 13.4115,
    lng: 121.1822,
    address: "San Vicente Central, Calapan City",
    phone: "0917-999-8888",
  },
  {
    id: 4,
    name: "Calapan City Hall",
    category: "Gov't",
    lat: 13.4132,
    lng: 121.1827,
    address: "Calapan City, Oriental Mindoro",
  },
  {
    id: 5,
    name: "Mindoro State University",
    category: "Schools",
    lat: 13.4127,
    lng: 121.185,
    address: "Sta. Isabel, Calapan City, Oriental Mindoro",
  },
  {
    id: 6,
    name: "Calapan Cathedral",
    category: "Landmarks",
    lat: 13.412,
    lng: 121.183,
    address: "Calapan City, Oriental Mindoro",
  },
]

// Category Buttons
const categories = [
  { key: "All", label: "All", icon: Landmark },
  { key: "Hospital", label: "Hospitals", icon: Hospital },
  { key: "Police", label: "Police", icon: Shield },
  { key: "Fire Dept", label: "Fire Dept", icon: FireExtinguisher },
  { key: "Gov't", label: "Gov't", icon: Building2 },
  { key: "Schools", label: "Schools", icon: School },
  { key: "Landmarks", label: "Landmarks", icon: Landmark },
]

// Default icon for establishments
const customIcon = new L.Icon({
  iconUrl: "https://cdn-icons-png.flaticon.com/512/684/684908.png",
  iconSize: [35, 35],
})

export default function MapPage() {
  const [userLocation, setUserLocation] = useState<{ lat: number; lng: number } | null>(null)
  const [activeCategory, setActiveCategory] = useState("All")

  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((pos) => {
        setUserLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude })
      })
    }
  }, [])

  // Filtered locations
  const filteredLocations =
    activeCategory === "All" ? locations : locations.filter((l) => l.category === activeCategory)

  return (
    <div className="w-full h-[100vh] flex flex-col">
      {/* Category Filter Buttons */}
      <div className="flex flex-wrap gap-3 p-4 bg-white shadow-md">
        {categories.map(({ key, label, icon: Icon }) => (
          <button
            key={key}
            onClick={() => setActiveCategory(key)}
            className={`flex items-center gap-2 px-4 py-2 rounded-full font-medium transition ${
              activeCategory === key ? "bg-orange-500 text-white" : "bg-gray-100 text-gray-800"
            }`}
          >
            <Icon className="w-4 h-4" />
            {label}
          </button>
        ))}
      </div>

      {/* Map */}
      <div className="flex-1">
        <MapContainer
          center={[13.4103, 121.1803]}
          zoom={14}
          className="w-full h-full"
          scrollWheelZoom={true}
        >
          {/* Map Layer */}
          <TileLayer
            attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          />

          {/* User Location */}
          {userLocation && (
            <Marker
              position={[userLocation.lat, userLocation.lng]}
              icon={
                new L.Icon({
                  iconUrl: "https://cdn-icons-png.flaticon.com/512/3177/3177361.png",
                  iconSize: [35, 35],
                })
              }
            >
              <Popup>You are here</Popup>
            </Marker>
          )}

          {/* Establishments */}
          {filteredLocations.map((loc) => (
            <Marker key={loc.id} position={[loc.lat, loc.lng]} icon={customIcon}>
              <Popup>
                <div className="text-sm">
                  <h3 className="font-bold text-gray-900">{loc.name}</h3>
                  <p className="text-gray-600">{loc.address}</p>
                  {loc.phone && <p className="text-gray-700 mt-1">☎ {loc.phone}</p>}

                  {/* Get Directions */}
                  {userLocation && (
                    <a
                      href={`https://www.google.com/maps/dir/${userLocation.lat},${userLocation.lng}/${loc.lat},${loc.lng}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="mt-2 inline-flex items-center gap-1 text-blue-600 font-medium"
                    >
                      <Navigation className="w-4 h-4" />
                      Get Directions
                    </a>
                  )}
                </div>
              </Popup>
            </Marker>
          ))}
        </MapContainer>
      </div>
    </div>
  )
}
